UPDATE dev_instrument_eodhd SET 
    name = 'Alphabet Inc Class A',
    exchange = 'NASDAQ',
    asset_type = 'Common Stock',
    currency = 'USD',
    ipo_date = '2004-08-19',
    country = '',
    sector = 'Communication Services',
    industry = 'Internet Content & Information',
    raw = '{"General": {"Code": "GOOGL", "Type": "Common Stock", "Name": "Alphabet Inc Class A", "Exchange": "NASDAQ", "CurrencyCode": "USD", "CurrencyName": "US Dollar", "CurrencySymbol": "$", "CountryName": "USA", "CountryISO": "US", "OpenFigi": "BBG009S39JX6", "ISIN": "US02079K3059", "LEI": "5493006MHB84DD0ZWV18", "PrimaryTicker": "GOOG.US", "CUSIP": "38259P706", "CIK": "0001652044", "EmployerIdNumber": "61-1767919", "FiscalYearEnd": "December", "IPODate": "2004-08-19", "InternationalDomestic": "International/Domestic", "Sector": "Communication Services", "Industry": "Internet Content & Information", "GicSector": "Communication Services", "GicGroup": "Media & Entertainment", "GicIndustry": "Interactive Media & Services", "GicSubIndustry": "Interactive Media & Services", "HomeCategory": "Domestic Primary", "IsDelisted": false, "Description": "Alphabet Inc. offers various products and platforms in the United States, Europe, the Middle East, Africa, the Asia-Pacific, Canada, and Latin America. It operates through Google Services, Google Cloud, and Other Bets segments. The Google Services segment provides products and services, including ads, Android, Chrome, devices, Gmail, Google Drive, Google Maps, Google Photos, Google Play, Search, and YouTube. It is also involved in the sale of apps and in-app purchases and digital content in the Google Play and YouTube; and devices, as well as in the provision of YouTube consumer subscription services. The Google Cloud segment offers AI infrastructure, Vertex AI platform, cybersecurity, data and analytics, and other services; Google Workspace that include cloud-based communication and collaboration tools for enterprises, such as Calendar, Gmail, Docs, Drive, and Meet; and other services for enterprise customers. The Other Bets segment sells healthcare-related and internet services. The company was incorporated in 1998 and is headquartered in Mountain View, California.", "Address": "1600 Amphitheatre Parkway, Mountain View, CA,