    industry = 'Semiconductors',
    raw = '{"General": {"Code": "NVDA", "Type": "Common Stock", "Name": "NVIDIA Corporation", "Exchange": "NASDAQ", "CurrencyCode": "USD", "CurrencyName": "US Dollar", "CurrencySymbol": "$", "CountryName": "USA", "CountryISO": "US", "OpenFigi": "BBG000BBJQV0", "ISIN": "US67066G1040", "LEI": "549300S4KLFTLO7GSQ80", "PrimaryTicker": "NVDA.US", "CUSIP": "67066G104", "CIK": "0001045810", "EmployerIdNumber": "94-3177549", "FiscalYearEnd": "January", "IPODate": "1999-01-22", "InternationalDomestic": "Domestic", "Sector": "Technology", "Industry": "Semiconductors", "GicSector": "Information Technology", "GicGroup": "Semiconductors & Semiconductor Equipment", "GicIndustry": "Semiconductors & Semiconductor Equipment", "GicSubIndustry": "Semiconductors", "HomeCategory": "Domestic", "IsDelisted": false, "Description": "NVIDIA Corporation, a computing infrastructure company, provides graphics and compute and networking solutions in the United States, Singapore, Taiwan, China, Hong Kong, and internationally. The Compute & Networking segment includes its Data Centre accelerated computing platforms and artificial intelligence solutions and software; networking; automotive platforms and autonomous and electric vehicle solutions; Jetson for robotics and other embedded platforms; and DGX Cloud computing services. The Graphics segment offers GeForce GPUs for gaming and PCs, the GeForce NOW game streaming service and related infrastructure, and solutions for gaming platforms; Quadro/NVIDIA RTX GPUs for enterprise workstation graphics; virtual GPU or vGPU software for cloud-based visual and virtual computing; automotive platforms for infotainment systems; and Omniverse software for building and operating industrial AI and digital twin applications. It also customized agentic solutions designed in collaboration with NVIDIA to accelerate enterprise AI adoption. The company''s products are used in gaming, professional visualization, data center, and automotive markets. It sells its products to original equipment manufacturers, original device manufacturers, system integrators and distributors, independent software vendors, cloud service providers, consumer internet companies, add-in board manufacturers, distributors, automotive manufacturers and tier-1 automotive suppliers, and other ecosystem participants. NVIDIA Corporation was incorporated in 1993 and is headquartered in Santa Clara, California.", "Address": "2788 San Tomas Expressway, Santa Clara, CA, United States, 95051", "AddressData": {"Street": "2788 San Tomas Expressway", "City": "Santa Clara", "State": "CA", "Country": "United States", "ZIP": "95051"}, "Listings": {"0": {"Code": "NVDC34", "Exchange": "SA", "Name": "NVIDIA Corporation"}}, "Officers": {"0": {"Name": "Mr. Jen-Hsun  Huang", "Title": "Co-Founder, CEO, President & Director", "YearBorn": "1963"}, "1": {"Name": "Ms. Colette M. Kress", "Title": "Executive VP & CFO", "YearBorn": "1967"}, "2": {"Name": "Ms. Debora  Shoquist", "Title": "Executive Vice President of Operations", "YearBorn": "1955"}, "3": {"Name": "Mr. Timothy S. Teter J.D.", "Title": "Executive VP, General Counsel & Secretary", "YearBorn": "1967"}, "4": {"Name": "Mr. Ajay K. Puri", "Title": "Executive Vice President of Worldwide Field Operations", "YearBorn": "1955"}, "5": {"Name": "Mr. Chris A. Malachowsky", "Title": "Co-Founder", "YearBorn": "NA"}, "6": {"Name": "Mr. Donald F. Robertson Jr.", "Title": "VP & Chief Accounting Officer", "YearBorn": "1969"}, "7": {"Name": "Prof. William J. Dally Ph.D.", "Title": "Chief Scientist & Senior VP of Research", "YearBorn": "1961"}, "8": {"Name": "Mr. Toshiya  Hari", "Title": "Vice President of Investor Relations & Strategic Finance", "YearBorn": "NA"}, "9": {"Name": "Ms. Mylene  Mangalindan", "Title": "VP of Corporate Communications", "YearBorn": "NA"}}, "Phone": "408 486 2000", "WebURL": "https://www.nvidia.com", "LogoURL": "/img/logos/US/NVDA.png", "FullTimeEmployees": 36000, "UpdatedAt": "2025-08-28"}, "Highlights": {"MarketC